  'Pl': 'Gezegenimsi bulutsu',
  'C+N': 'Kume + bulutsu',
  'Ast': 'Yildiz toplulugu',
  'Kt': 'Galakside dugum',
  '***': 'Uclu yildiz',
  'D*': 'Cift yildiz',
  '*': 'Yildiz',
  '?': 'Belirsiz',
};

